import unittest
from unittest.mock import patch
from checkout import _discount, quote
class CheckoutTests(unittest.TestCase):
    def test_delegates(self):
        with patch("checkout._discount",return_value=42) as helper:
            quote(100)
            helper.assert_called_once_with(100)
    def test_matches_helper(self):
        self.assertEqual(quote(120)["total"],round(_discount(120),2))
